import{_ as d,C as s,o as i,c as n,j as a,a as r,E as o,a2 as c}from"./chunks/framework.BxGh02fV.js";const y=JSON.parse('{"title":"Get started","description":"","frontmatter":{"title":"Get started"},"headers":[],"relativePath":"en/agent/demarrer.md","filePath":"en/agent/demarrer.md"}'),l={name:"en/agent/demarrer.md"};function f(h,e,m,p,u,g){const t=s("Ask");return i(),n("div",null,[e[0]||(e[0]=a("h1",{id:"get-started",tabindex:"-1"},[r("Get started "),a("a",{class:"header-anchor",href:"#get-started","aria-label":'Permalink to "Get started"'},"​")],-1)),e[1]||(e[1]=a("p",null,"This journey opens a job: create a new project, take over a project that already exists, or connect Effortless to your agent. You come here once per project, or once per machine for the deployment.",-1)),e[2]||(e[2]=a("h2",{id:"what-you-ask-the-agent",tabindex:"-1"},[r("What you ask the agent "),a("a",{class:"header-anchor",href:"#what-you-ask-the-agent","aria-label":'Permalink to "What you ask the agent"'},"​")],-1)),o(t,{say:"Create an Effortless project here, with the tauri-react-tailwind model.",verb:"effortless_init",family:"installation",args:'{"model_id":"tauri-react-tailwind"}'}),o(t,{say:"Which stack models exist? Show me the detail of rust.",verb:"effortless_stack_model_list",family:"stacks"}),o(t,{say:"This repository already exists: prepare its migration to Effortless, without writing anything for now.",verb:"effortless_migrate_init",family:"installation",args:'{"confirm":false}'}),o(t,{say:"Apply the migration.",verb:"effortless_migrate_apply",family:"installation",args:'{"dry_run":false}'}),o(t,{say:"Bring this project up to date with the current Effortless version.",verb:"effortless_migrate",family:"installation",args:'{"confirm":true}'}),o(t,{say:"Move the root code into codebase/.",verb:"effortless_codebase_relocate",family:"installation",args:'{"dry_run":false}'}),o(t,{say:"Deploy Effortless into my agents.",verb:"effortless_deploy",family:"installation"}),e[3]||(e[3]=c('<h2 id="what-the-agent-does" tabindex="-1">What the agent does <a class="header-anchor" href="#what-the-agent-does" aria-label="Permalink to &quot;What the agent does&quot;">​</a></h2><h3 id="create-a-new-project" tabindex="-1">Create a new project <a class="header-anchor" href="#create-a-new-project" aria-label="Permalink to &quot;Create a new project&quot;">​</a></h3><ol><li><a href="/Effortless/en/reference/mcp/stacks.html#stack-model-list"><code>effortless_stack_model_list</code></a> lists the available models (usable before any project).</li><li><a href="/Effortless/en/reference/mcp/stacks.html#stack-model-show"><code>effortless_stack_model_show</code></a> details one model: variables, build strategy, test/lint/run cycle. Parameter: <code>model_id</code>.</li><li><a href="/Effortless/en/reference/mcp/installation.html#init"><code>effortless_init</code></a> creates the project in the current directory. It passes <code>model_id</code> to apply the model (folder tree and standards under <code>.ai/ndd/</code>), and can pass <code>project_name</code>, <code>description</code>, <code>context</code> (<code>greenfield</code>, <code>existing</code> or <code>migration</code>). It also writes <code>AGENTS.md</code> and <code>CLAUDE.md</code> (see <a href="./">With an agent</a>).</li></ol><h3 id="take-over-an-existing-project" tabindex="-1">Take over an existing project <a class="header-anchor" href="#take-over-an-existing-project" aria-label="Permalink to &quot;Take over an existing project&quot;">​</a></h3><ol><li><a href="/Effortless/en/reference/mcp/installation.html#migrate-init"><code>effortless_migrate_init</code></a> analyzes the repository. With <code>confirm: false</code> (default) it is a preview that writes nothing; with <code>confirm: true</code> it writes the configuration, an epic, a story and <code>migration_plan.json</code>.</li><li><a href="/Effortless/en/reference/mcp/installation.html#migrate-apply"><code>effortless_migrate_apply</code></a> carries out the moves in the plan. With <code>dry_run: true</code> it is an audit; with <code>dry_run: false</code> it really moves the files and writes <code>migration_report.md</code>.</li><li><a href="/Effortless/en/reference/mcp/installation.html#codebase-relocate"><code>effortless_codebase_relocate</code></a>, if you want it, moves the root code under <code>codebase/&lt;stack&gt;/</code>. <code>dry_run</code> defaults to <code>true</code>.</li></ol><h3 id="bring-a-project-up-to-date" tabindex="-1">Bring a project up to date <a class="header-anchor" href="#bring-a-project-up-to-date" aria-label="Permalink to &quot;Bring a project up to date&quot;">​</a></h3><p><a href="/Effortless/en/reference/mcp/installation.html#migrate"><code>effortless_migrate</code></a> replays the migrations up to the current schema. <code>confirm: false</code> (default) shows what would be done; <code>confirm: true</code> applies it, with <code>.bak</code> backups. The old verbs <a href="/Effortless/en/reference/mcp/installation.html#migrate-nomenclature"><code>effortless_migrate_nomenclature</code></a> and <a href="/Effortless/en/reference/mcp/installation.html#migrate-state"><code>effortless_migrate_state</code></a> are deprecated: they are aliases of <code>effortless_migrate</code>.</p><h3 id="deploy" tabindex="-1">Deploy <a class="header-anchor" href="#deploy" aria-label="Permalink to &quot;Deploy&quot;">​</a></h3><p><a href="/Effortless/en/reference/mcp/installation.html#deploy"><code>effortless_deploy</code></a> installs the server in your clients, the global guide and, for Claude Code, the status bar (see <a href="./">With an agent</a>). <code>targets</code> limits the clients, <code>scope</code> chooses <code>user</code> (default) or a project, <code>grant_permissions: true</code> also sets the server&#39;s permissions. It is an action on your machine: the agent runs it when you ask.</p><h2 id="what-you-get" tabindex="-1">What you get <a class="header-anchor" href="#what-you-get" aria-label="Permalink to &quot;What you get&quot;">​</a></h2><ul><li>A project with <code>effortless.json</code>, <code>.effortless/</code>, the model&#39;s folder tree and, if the model carries any, the standards under <code>.ai/ndd/</code>.</li><li><code>AGENTS.md</code> and <code>CLAUDE.md</code> at the root.</li><li>For a takeover: <code>migration_plan.json</code>, then <code>migration_report.md</code> once the plan is applied.</li><li>On screen: the project opens from the workspace picker (<a href="/Effortless/en/guide/start.html">Open a workspace</a>); the deployment shows in <strong>Preferences › MCP &amp; Skills</strong> (<a href="/Effortless/en/guide/preferences.html">Profile and preferences</a>).</li></ul><h2 id="when-the-agent-is-refused" tabindex="-1">When the agent is refused <a class="header-anchor" href="#when-the-agent-is-refused" aria-label="Permalink to &quot;When the agent is refused&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Situation</th><th>What the refusal says</th><th>What to do</th></tr></thead><tbody><tr><td>A project verb is called outside a project</td><td><code>mcp:racineProjetIntrouvable</code></td><td>Set <code>EFFORTLESS_PROJECT</code> in the server configuration if the project exists elsewhere; otherwise <code>effortless_init</code> creates one here.</td></tr><tr><td><code>EFFORTLESS_PROJECT</code> points to a folder with no project</td><td><code>mcp:projetInexistantALEndroitDeclare</code></td><td>Call <code>effortless_init</code> there: your configuration is not at fault.</td></tr><tr><td><code>effortless_init</code> on an already initialized folder</td><td><code>create:alreadyExists</code></td><td>Pass <code>force: true</code> to overwrite, or pick another directory.</td></tr><tr><td><code>effortless_init</code> with an unknown <code>model_id</code></td><td><code>create:modelUnknown</code></td><td><code>effortless_stack_model_list</code> names the available models. Nothing is written.</td></tr><tr><td><code>effortless_init</code> with a name made of spaces</td><td><code>create:blankName</code></td><td>Pass a <code>project_name</code> with at least one non-blank character.</td></tr><tr><td><code>effortless_migrate_init</code> on an already initialized project</td><td><code>adopt:alreadyInitialized</code></td><td>Pass <code>force: true</code> (a <code>.bak</code> backup is written).</td></tr><tr><td><code>effortless_migrate_apply</code> with no plan</td><td><code>adopt:planNotFound</code></td><td><code>effortless_migrate_init</code> writes the migration plan.</td></tr><tr><td><code>effortless_stack_model_show</code> with an unknown model</td><td>&quot;model … not found&quot; message, no code</td><td><code>effortless_stack_model_list</code> gives the valid ids.</td></tr><tr><td><code>effortless_codebase_relocate</code> in semi-auto mode</td><td>not a refusal: the reply carries <code>gated: true</code> and no moves</td><td>Switch the project to <code>full</code> mode with <code>effortless_mode_set</code>.</td></tr></tbody></table><p><code>init</code> with <code>force: true</code> also empties <code>.effortless/epics/</code>, <code>backlog.json</code> and <code>state.json</code>: the agent only does it at your explicit request.</p>',14))])}const w=d(l,[["render",f]]);export{y as __pageData,w as default};
